/**
 * The calendar: real Formula 1 circuits, venues and countries.
 *
 * ## Layouts
 *
 * The centreline for every circuit is real data, in `circuitData.js`, generated by
 * `scripts/fetch-circuits.mjs` from published centrelines and -- where none is
 * published -- from the circuit outline's medial axis. See that script for sources
 * and attribution.
 *
 * What is in this file is everything *about* a circuit: name, venue, city,
 * country, corner count, lap character, surface grip, race distance, and the
 * theme the renderer uses for its sky and grass.
 *
 * ## The pin format, retained
 *
 * `circuitShapes.js` still offers `profileFromPins`, which builds a loop from a
 * base radius plus corner pins. Nothing in the game uses it for a real circuit any
 * more -- it is kept because the radial-profile approach is still the only way to
 * generate a *new* closed loop, and its failure modes are documented where it is
 * implemented.
 *
 * Names of circuits, teams and drivers are used nominatively, to identify the
 * real-world subjects this game is a homage to. No team or series asset is
 * included or reproduced.
 */

import { centrelineFor } from './circuitData.js';

/**
 * Rotate a ring of points by `angle` degrees.
 * @param {Array<{x: number, z: number}>} points
 * @param {number} angle degrees
 */
/*
 * Layouts are the real centrelines.
 *
 * Generated by `scripts/fetch-circuits.mjs` from published centreline data and,
 * where none is published, from the circuit outline's medial axis. Each is
 * rescaled so the lap length matches the real one.
 *
 * These were radial profiles until recently -- a base radius plus corner pins,
 * which cannot produce a specific layout because a star-shaped loop has no room
 * for a hairpin next to a long straight. Real centreline data does, so the whole
 * generator was replaced rather than approximated harder.
 */

/**
 * The real centreline for a circuit, in metres.
 *
 * `angle` rotates the loop so the start/finish straight and the grid sit sensibly
 * relative to the corner sequence; rotation is free, shape is not, so this is the
 * only geometric freedom left.
 */
export function circuitLayout(circuit) {
  const points = centrelineFor(circuit.id);
  const rotation = ((circuit.angle ?? 0) * Math.PI) / 180;
  if (!rotation) return points;
  const cos = Math.cos(rotation);
  const sin = Math.sin(rotation);
  return points.map((point) => ({ x: point.x * cos - point.z * sin, z: point.x * sin + point.z * cos }));
}

