/** Every circuit, with its generated control points attached. */
export const CIRCUITS = RAW.map((circuit) => ({
  ...circuit,
  scale: circuit.scale ?? 1,
  controlPoints: circuitLayout(circuit)
}));

const BY_ID = new Map(CIRCUITS.map((circuit) => [circuit.id, circuit]));

/**
 * Look up a circuit by id.
 * @param {string} id
 */
export function getCircuit(id) {
  const circuit = BY_ID.get(id);
  if (!circuit) throw new Error(`Unknown circuit "${id}"`);
  return circuit;
}

/** All team names, for the entry list. */
export function circuitIds() {
  return CIRCUITS.map((circuit) => circuit.id);
}